html:
{% set pos_settings = frappe.get_doc("Santu POS Settings") %}
{% set company_addr_name = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, "parent") %}
{% set company_address = doc.company_address_display %}
{% set company_phone = None %}
{% set company_gstin = frappe.db.get_value("Company", doc.company, "gstin") %}
{% set company_website = frappe.db.get_value("Company", doc.company, "website") %}
{% set company_email = frappe.db.get_value("Company", doc.company, "email") %}
{% if company_addr_name %}
	{% set caddr2 = frappe.get_doc("Address", company_addr_name) %}
	{% set company_place = caddr2.county or caddr2.city %}
	{% set company_address = (caddr2.address_line1 + ", " if caddr2.address_line1 else "") + (caddr2.address_line2 + ", " if caddr2.address_line2 else "") + company_place + ", " + caddr2.state + " " + (caddr2.pincode or "") %}
	{% set company_phone = caddr2.phone %}
{% endif %}
{% set customer_doc = frappe.get_doc("Customer", doc.customer) if doc.customer else None %}
{% set customer_mobile = (customer_doc.mobile_no if customer_doc else None) or doc.contact_mobile %}
{% set customer_gstin = customer_doc.gstin if customer_doc else None %}
{% set customer_village = customer_doc.santu_village if customer_doc else None %}
{% set customer_city = None %}
{% set customer_addr_line = None %}
{% set customer_state = None %}
{% if customer_doc and customer_doc.customer_primary_address %}
	{% set caddr = frappe.get_doc("Address", customer_doc.customer_primary_address) %}
	{% set customer_addr_line = caddr.address_line1 %}
	{% set customer_city = caddr.city %}
	{% set customer_state = caddr.state %}
{% endif %}
{% set customer_place = frappe.call("santu_hardware.santu_hardware.api.party_address_line", party_type="Customer", party=doc.customer) if doc.customer else None %}
{% set due = doc.outstanding_amount | flt %}
{% set total_qty = doc.items | sum(attribute="qty") %}
{% set balances = frappe.call("santu_hardware.santu_hardware.api.get_customer_balance_summary", customer=doc.customer, exclude_doctype=doc.doctype, exclude_name=doc.name) %}
{% set previous_balance = balances.previous_balance | flt %}
{% set current_balance = previous_balance + due %}

<div class="santu-bill">
	<table class="santu-bill-header-table">
		<tr>
			<td style="width: 60%">
				{% set a4_logo = frappe.call("santu_hardware.santu_hardware.api.get_a4_logo_data_uri") if frappe.db.get_single_value("Santu POS Settings", "show_logo_on_a4_bill") else None %}
				{% if a4_logo %}
					<div style="margin-bottom: 8px;"><img src="{{ a4_logo }}" style="width: {{ pos_settings.a4_logo_width or 40 }}%; max-width: 100%; height: auto;"></div>
				{% else %}
					<div class="santu-bill-shop-name">{{ doc.company }}</div>
				{% endif %}
				<div class="santu-bill-shop-meta">
					{{ company_address or "" }}<br>
					{% if company_phone %}Phone: {{ company_phone }}<br>{% endif %}
					{% if company_gstin %}<b>GSTIN:</b> {{ company_gstin }}{% endif %}
				</div>
			</td>
			<td class="santu-bill-title-block" style="width: 40%">
				<div class="santu-bill-title">{% if doc.docstatus == 1 %}SALE BILL{% else %}QUOTATION{% endif %}</div>
				<div class="santu-bill-meta-row"><b>Bill No:</b> {{ frappe.call("santu_hardware.santu_hardware.api.bill_label", bill_no=doc.santu_bill_no) }}</div>
				<div class="santu-bill-meta-row"><b>Date:</b> {{ doc.get_formatted("posting_date") }}</div>
				{% if due > 0 and doc.due_date %}<div class="santu-bill-meta-row"><b>Due Date:</b> {{ doc.get_formatted("due_date") }}</div>{% endif %}
				<span class="santu-bill-status-pill {{ 'santu-bill-status-due' if due > 0 else 'santu-bill-status-paid' }}">
					{{ "Payment Due" if due > 0 else "Paid" }}
				</span>
			</td>
		</tr>
	</table>

	<table class="santu-bill-customer-table">
		<tr>
			<td>
				<div class="santu-bill-customer-label">Billed To</div>
				<div class="santu-bill-customer-name">{{ doc.customer_name }}</div>
				{% if customer_mobile %}<div class="santu-bill-customer-detail">Phone: {{ customer_mobile }}</div>{% endif %}
	{% if customer_gstin %}<div class="santu-bill-customer-detail">GSTIN: {{ customer_gstin }}</div>{% endif %}
				{% if customer_place %}<div class="santu-bill-customer-detail">{{ customer_place }}</div>{% endif %}
			</td>
		</tr>
	</table>

	<table class="santu-bill-items">
		<thead>
			<tr>
				<th style="width: 6%">#</th>
				<th style="width: 40%">Item</th>
				<th class="num" style="width: 15%">Qty</th>
				<th class="num" style="width: 18%">Rate</th>
				<th class="num" style="width: 21%">Amount</th>
			</tr>
		</thead>
		<tbody>
			{% for item in doc.items %}
			<tr>
				<td>{{ loop.index }}</td>
				<td>{{ item.item_name }}</td>
				<td class="num">{{ item.qty | int if item.qty == item.qty | int else item.qty }} {{ frappe.call("santu_hardware.santu_hardware.api.uom_abbr", uom=item.uom) }}</td>
				<td class="num">{{ item.get_formatted("rate") }}</td>
				<td class="num">{{ item.get_formatted("amount") }}</td>
			</tr>
			{% endfor %}
		</tbody>
		<tfoot>
			<tr>
				<td colspan="2"></td>
				<td class="num">Total Qty</td>
				<td class="num" colspan="2">{{ total_qty | int if total_qty == total_qty | int else total_qty }}</td>
			</tr>
		</tfoot>
	</table>

	<table class="santu-bill-totals-table">
		{#- Shown only for a discount someone actually gave. Anything under a
		    rupee is the app's own rounding reconciliation: a line discount is
		    folded into a 2-decimal rate, and the few paise that will not
		    divide evenly across the quantity come back as an invoice-level
		    discount. ERPNext also RE-DERIVES this field while printing
		    (grand_total - total), so it arrives negative and the template's
		    own "-" printed "- Rs -0.02" on a customer's bill (2026-09-04).
		    abs() kills the double minus; the >= 1 gate keeps rounding paise
		    off the bill entirely. -#}
		{% set shown_discount = doc.discount_amount | flt | abs %}
		{% if shown_discount >= 1 %}
		<tr><td>Discount</td><td class="value">- {{ frappe.format_value(shown_discount, {"fieldtype": "Currency"}) }}</td></tr>
		{% endif %}
		<tr class="grand"><td>Total</td><td class="value">{{ doc.get_formatted("grand_total") }}</td></tr>
		<tr><td>Paid</td><td class="value">{{ doc.get_formatted("paid_amount") }}</td></tr>
		{% if due > 0 %}
		<tr class="due"><td>Balance Due (This Bill)</td><td class="value">{{ doc.get_formatted("outstanding_amount") }}</td></tr>
		{% endif %}
	</table>
	<div class="santu-bill-words">{{ doc.in_words }}</div>

	<table class="santu-bill-panels">
		<tr>
			<td>
				<div class="santu-bill-panel">
					<div class="santu-bill-panel-title">Account Summary</div>
					<div class="santu-bill-panel-row"><span>Previous Balance</span><span>Rs. {{ "%.2f" | format(previous_balance) }}</span></div>
					<div class="santu-bill-panel-row"><span>Received Today</span><span>Rs. {{ "%.2f" | format(doc.paid_amount | flt) }}</span></div>
					<div class="santu-bill-panel-row emphasis {{ 'ok' if current_balance <= 0 else '' }}"><span>Current Balance</span><span>Rs. {{ "%.2f" | format(current_balance) }}</span></div>
				</div>
			</td>
		</tr>
	</table>

	<div class="santu-bill-signature-block">
		<div class="santu-bill-signature-line">For {{ doc.company }}</div>
		<div class="santu-bill-signature-sub">Authorised Signatory</div>
	</div>

	<div class="santu-bill-footer">
		<div class="thanks">Thank you for shopping with {{ doc.company }}!</div>
		{% if company_website or company_email %}
		<div class="santu-bill-contact">
			{% if company_website %}<a href="{{ company_website if company_website.startswith('http') else 'https://' + company_website }}">{{ company_website | replace("https://", "") | replace("http://", "") }}</a>{% endif %}{% if company_website and company_email %} &nbsp;|&nbsp; {% endif %}{% if company_email %}<a href="mailto:{{ company_email }}">{{ company_email }}</a>{% endif %}
		</div>
		{% endif %}
		<div class="legal">Goods once sold can only be exchanged, not refunded. Bill is required for exchange. E&amp;OE.</div>{% set loyalty = frappe.call("santu_hardware.santu_hardware.api.get_customer_loyalty_summary", customer=doc.customer, invoice_doctype=doc.doctype, invoice_name=doc.name) %}{% if loyalty.enabled and loyalty.earned_this_bill %}<div class="santu-bill-reward">Reward Points Earned: {{ loyalty.earned_label }}</div>{% endif %}{% if loyalty.show_reward_terms %}<div class="santu-bill-tnc">T&amp;C: बिल की पूरी भुगतान 2 दिन के अंदर न होने पर इस बिल के रिवॉर्ड पॉइंट्स समाप्त हो जाएंगे।</div>{% endif %}
	</div>
</div>

{% set pos_settings = frappe.get_doc("Santu POS Settings") %}
{% set paper_width = pos_settings.paper_width or "80mm" %}
{% set inner_width = "72mm" if paper_width == "80mm" else "50mm" %}

{% set gstin = frappe.db.get_value("Company", doc.company, "gstin") %}
{% set company_addr_name = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, "parent") %}
{% set company_address = "" %}
{% set company_phone = None %}
{% if company_addr_name %}
	{% set caddr2 = frappe.get_doc("Address", company_addr_name) %}
	{% set company_address = (caddr2.address_line1 + ", " if caddr2.address_line1 else "") + (caddr2.address_line2 + ", " if caddr2.address_line2 else "") + caddr2.city %}
	{% set company_phone = caddr2.phone %}
{% endif %}
{% set customer_doc = frappe.get_doc("Customer", doc.customer) if doc.customer else None %}
{% set customer_mobile = (customer_doc.mobile_no if customer_doc else None) or doc.contact_mobile %}
{% set customer_gstin = customer_doc.gstin if customer_doc else None %}
{% set customer_addr_name = frappe.db.get_value("Dynamic Link", {"link_doctype": "Customer", "link_name": doc.customer, "parenttype": "Address"}, "parent") if doc.customer else None %}
{% set customer_address = "" %}
{% if customer_addr_name %}
	{% set caddr3 = frappe.get_doc("Address", customer_addr_name) %}
	{# Frappe seeds a new Address's address_line1 from its title, which for a
	   customer-linked address is the customer's own name -- so an address
	   created without the shop typing a real street line prints "Address:
	   Chandra Prakash" right under a row that already says "Customer:
	   Chandra Prakash" (found 2026-08-23: two-thirds of a small sample had
	   this). Skip that line only when it's just repeating the name already
	   shown above; address_line2 and city are never auto-filled that way. #}
	{% set line1 = caddr3.address_line1 if caddr3.address_line1 and caddr3.address_line1.strip().lower() != (doc.customer_name or "").strip().lower() else None %}
	{# 2026-08-28: address is now ONE free-text field (address_line1) app-wide
	   -- no separate village/district split any more. address_line2 and
	   city are leftover columns on older Address records and printing them
	   here duplicated the same place name that's already inside
	   address_line1. #}
	{% set customer_address = line1 or "" %}
{% endif %}
{% set discount = doc.discount_amount | flt %}
{% set upi_qr = frappe.call("santu_hardware.santu_hardware.api.get_upi_qr_data_uri", amount=doc.paid_amount, invoice_name=doc.name, scale=12) %}

<div class="santu-thermal" style="width: {{ inner_width }};">
	{% set bill_logo = frappe.call("santu_hardware.santu_hardware.api.get_bill_logo_data_uri") if pos_settings.show_logo_on_bill else None %}
	{% if bill_logo %}<div class="t-center"><img src="{{ bill_logo }}" style="width: {{ pos_settings.thermal_logo_width or 65 }}mm; max-width: 100%; height: auto;"></div>{% else %}<div class="t-center t-bold t-xl">{{ doc.company }}</div>{% endif %}
	{% if company_address %}<div class="t-center t-sm">{{ company_address }}</div>{% endif %}
	{% if company_phone %}<div class="t-center t-sm">Ph: {{ company_phone }}</div>{% endif %}
	{% if gstin %}<div class="t-center t-sm">GSTIN: {{ gstin }}</div>{% endif %}

	<div class="t-dash"></div>
	<div class="t-center t-bold">{% if doc.docstatus == 1 %}INVOICE{% else %}QUOTATION{% endif %}</div>
	<div class="t-dash"></div>

	<div class="t-row"><span>Bill No</span><span>{{ frappe.call("santu_hardware.santu_hardware.api.bill_label", bill_no=doc.santu_bill_no) }}</span></div>
	<div class="t-row"><span>Date</span><span>{{ doc.get_formatted("posting_date") }} {{ doc.get_formatted("posting_time") }}</span></div>
	<div class="t-row"><span>Customer</span><span>{{ doc.customer_name }}</span></div>
	{% if customer_mobile %}<div class="t-row"><span>Phone</span><span>{{ customer_mobile }}</span></div>{% endif %}
	{% if customer_gstin %}<div class="t-row"><span>GSTIN</span><span>{{ customer_gstin }}</span></div>{% endif %}
	{% if customer_address %}<div class="t-row"><span>Address</span><span>{{ customer_address }}</span></div>{% endif %}

	<div class="t-dash"></div>

	{% for item in doc.items %}
	<div class="t-item-name">{{ loop.index }}. {{ item.item_name }}</div>
	<div class="t-row t-sm">
		<span>{{ item.qty | int if item.qty == item.qty | int else item.qty }} {{ frappe.call("santu_hardware.santu_hardware.api.uom_abbr", uom=item.uom) }} &times; {{ item.get_formatted("rate") }}</span>
		<span>{{ item.get_formatted("amount") }}</span>
	</div>
	{% endfor %}

	{% if discount > 0 %}<div class="t-row"><span>Discount</span><span>-{{ doc.get_formatted("discount_amount") }}</span></div>{% endif %}
	<div class="t-dash"></div>
	<div class="t-row t-bold t-lg"><span>TOTAL</span><span>{{ doc.get_formatted("grand_total") }}</span></div>
	<div class="t-row t-sm"><span>PAID</span><span>{{ doc.get_formatted("paid_amount") }}</span></div>

	{% if upi_qr %}
	<div class="t-dash"></div>
	<div class="t-center t-sm t-bold">Scan &amp; Pay</div>
	<div class="t-center"><img src="{{ upi_qr }}" style="width: 28mm; height: 28mm; image-rendering: pixelated; image-rendering: -moz-crisp-edges; image-rendering: crisp-edges;"></div>
	<div class="t-center t-sm">UPI ID: {{ frappe.call("santu_hardware.santu_hardware.api.get_upi_display_id") }}</div>
	{% endif %}

	<div class="t-dash"></div>
	<div class="t-center t-bold">Thank You!</div>
	<div class="t-center t-sm">Visit Again</div>
</div>

{% set pos_settings = frappe.get_doc("Santu POS Settings") %}
{% set paper_width = pos_settings.paper_width or "80mm" %}
{% set inner_width = "72mm" if paper_width == "80mm" else "50mm" %}

{% set gstin = frappe.db.get_value("Company", doc.company, "gstin") %}
{% set company_addr_name = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, "parent") %}
{% set company_address = "" %}
{% set company_phone = None %}
{% if company_addr_name %}
	{% set caddr2 = frappe.get_doc("Address", company_addr_name) %}
	{% set company_place = caddr2.county or caddr2.city %}
	{% set company_address = (caddr2.address_line1 + ", " if caddr2.address_line1 else "") + (caddr2.address_line2 + ", " if caddr2.address_line2 else "") + company_place + ", " + caddr2.state + " " + (caddr2.pincode or "") %}
	{% set company_phone = caddr2.phone %}
{% endif %}
{% set customer_doc = frappe.get_doc("Customer", doc.customer) if doc.customer else None %}
{% set customer_mobile = (customer_doc.mobile_no if customer_doc else None) or doc.contact_mobile %}
{% set customer_gstin = customer_doc.gstin if customer_doc else None %}
{% set customer_address = frappe.call("santu_hardware.santu_hardware.api.party_address_line", party_type="Customer", party=doc.customer) if doc.customer else "" %}
{% set discount = doc.discount_amount | flt %}
{% set paid = doc.paid_amount | flt %}
{% set payment_mode = doc.payments[0].mode_of_payment if doc.payments else None %}
{% set upi_qr = frappe.call("santu_hardware.santu_hardware.api.get_upi_qr_data_uri", amount=doc.paid_amount, invoice_name=doc.name, scale=12) %}
{# posting_time arrives as a timedelta through the PDF path but as a plain
   "HH:MM:SS" string through Desk's own print view — calling .total_seconds()
   blindly crashed the whole format there with "'str object' has no attribute
   'total_seconds'" (found 2026-08-23 opening this format from the Print
   button). Stringifying first works for both: str(timedelta) is also
   "H:MM:SS", so the same split parses either one. #}
{% set t_parts = (doc.posting_time | string).split(":") %}
{% set t_hh24 = (t_parts[0] | int) % 24 if t_parts | length > 1 else 0 %}
{% set t_mm = t_parts[1] | int if t_parts | length > 1 else 0 %}
{% set t_ampm = "AM" if t_hh24 < 12 else "PM" %}
{% set t_hh12 = t_hh24 % 12 %}
{% set t_hh12 = 12 if t_hh12 == 0 else t_hh12 %}
{% set posting_time_12h = "%02d:%02d %s" % (t_hh12, t_mm, t_ampm) %}

{# ---------------------------------------------------------------------------
   Which layout to print. The preview passes ?santu_style=... so the shop can
   look at any template without changing what actually prints; a real print has
   no such param and falls back to the saved default in Santu POS Settings.
   Every template below is a genuinely different slip -- before this they were
   seven names that all rendered the identical bill.
--------------------------------------------------------------------------- #}
{% set style = frappe.form_dict.get("santu_style") or pos_settings.invoice_template_style or "Standard Bill" %}
{% set STYLES = {
	"Standard Bill":            {"cls": "",          "cust": 1, "addr": 1, "price": 1, "qr": 1, "code": 0, "disc": 0, "acct": 1, "pay": 0, "sign": 0, "foot": 1, "banner": ""},
	"Compact Bill":             {"cls": "v-compact", "cust": 1, "addr": 1, "price": 1, "qr": 0, "code": 0, "disc": 0, "acct": 0, "pay": 0, "sign": 0, "foot": 0, "banner": ""},
	"Detailed Bill":            {"cls": "",          "cust": 1, "addr": 1, "price": 1, "qr": 1, "code": 1, "disc": 1, "acct": 1, "pay": 1, "sign": 0, "foot": 1, "banner": ""},
	"Simple Cash Bill":         {"cls": "",          "cust": 0, "addr": 0, "price": 1, "qr": 0, "code": 0, "disc": 0, "acct": 0, "pay": 0, "sign": 0, "foot": 1, "banner": ""},
	"Customer Copy":            {"cls": "",          "cust": 1, "addr": 1, "price": 1, "qr": 1, "code": 0, "disc": 0, "acct": 1, "pay": 0, "sign": 0, "foot": 1, "banner": "CUSTOMER COPY"},
	"Duplicate / Office Copy":  {"cls": "",          "cust": 1, "addr": 1, "price": 1, "qr": 0, "code": 1, "disc": 0, "acct": 1, "pay": 0, "sign": 1, "foot": 0, "banner": "DUPLICATE - OFFICE COPY"},
	"Bill + Payment Receipt":   {"cls": "",          "cust": 1, "addr": 1, "price": 1, "qr": 1, "code": 0, "disc": 0, "acct": 1, "pay": 1, "sign": 0, "foot": 1, "banner": ""},
	"Delivery Slip (No Rates)": {"cls": "",          "cust": 1, "addr": 1, "price": 0, "qr": 0, "code": 1, "disc": 0, "acct": 0, "pay": 0, "sign": 1, "foot": 0, "banner": "DELIVERY SLIP - NOT A BILL"},
	"Large Print Bill":         {"cls": "v-large",   "cust": 1, "addr": 1, "price": 1, "qr": 1, "code": 0, "disc": 0, "acct": 1, "pay": 0, "sign": 0, "foot": 1, "banner": ""},
	"Udhaar / Balance Bill":    {"cls": "",          "cust": 1, "addr": 1, "price": 1, "qr": 1, "code": 0, "disc": 0, "acct": 1, "pay": 0, "sign": 1, "foot": 0, "banner": ""},
	"Minimal Slip":             {"cls": "v-compact", "cust": 0, "addr": 0, "price": 1, "qr": 0, "code": 0, "disc": 0, "acct": 0, "pay": 0, "sign": 0, "foot": 0, "banner": ""}
} %}
{% set v = STYLES.get(style, STYLES["Standard Bill"]) %}
{% set is_udhaar = style == "Udhaar / Balance Bill" %}
{% set is_minimal = style == "Minimal Slip" %}

{% set balances = frappe.call("santu_hardware.santu_hardware.api.get_customer_balance_summary", customer=doc.customer, exclude_doctype=doc.doctype, exclude_name=doc.name) %}
{% set previous_balance = (balances.previous_balance | float) if balances else 0 %}
{% set this_due = doc.outstanding_amount | float %}
{% set current_balance = previous_balance + this_due %}

<div class="santu-thermal {{ v.cls }}" style="width: {{ inner_width }};">
	{% set bill_logo = frappe.call("santu_hardware.santu_hardware.api.get_bill_logo_data_uri") if pos_settings.show_logo_on_bill else None %}
	{% if bill_logo %}<div class="t-center"><img src="{{ bill_logo }}" style="width: 65mm; max-width: 100%; height: auto;"></div>{% else %}<div class="t-center t-bold t-xl">{{ doc.company }}</div>{% endif %}
	{% if v.addr and company_address %}<div class="t-center t-sm">{{ company_address }}</div>{% endif %}
	{% if v.addr and gstin %}<div class="t-center t-sm">GSTIN: {{ gstin }}</div>{% endif %}
	{% if company_phone %}<div class="t-center t-sm">Ph: {{ company_phone }}</div>{% endif %}

	<div class="t-dash"></div>
	{% if v.banner %}<div class="t-center t-bold t-banner">{{ v.banner }}</div>{% endif %}
	<div class="t-center t-bold">{% if not v.price %}GOODS DELIVERY{% elif doc.docstatus == 1 %}INVOICE{% else %}QUOTATION{% endif %}</div>
	<div class="t-dash"></div>

	{% if is_udhaar and current_balance > 0 %}
	<div class="t-duebox">
		<div class="t-center t-sm t-bold">BAAKI / BALANCE DUE</div>
		<div class="t-center t-bold t-due">Rs. {{ "%.2f"|format(current_balance) }}</div>
	</div>
	{% endif %}

	<div class="t-row"><span>Bill No.</span><span>{{ frappe.call("santu_hardware.santu_hardware.api.bill_label", bill_no=doc.santu_bill_no) }}</span></div>
	<div class="t-row"><span>Date</span><span>{{ doc.get_formatted("posting_date") }} {{ posting_time_12h }}</span></div>
	{% if v.cust %}
	<div class="t-row"><span>Customer</span><span>{{ doc.customer_name }}</span></div>
	{% if customer_mobile %}<div class="t-row"><span>Phone</span><span>{{ customer_mobile }}</span></div>{% endif %}
	{% if customer_gstin %}<div class="t-row"><span>GSTIN</span><span>{{ customer_gstin }}</span></div>{% endif %}
