{% set previous_balance = (balances.previous_balance | float) if balances else 0 %}
{% set this_due = doc.outstanding_amount | float %}
{% set current_balance = previous_balance + this_due %}

<div class="santu-thermal {{ v.cls }}" style="width: {{ inner_width }};">
