	{% if company_phone %}<div class="t-center t-sm">Ph: {{ company_phone }}</div>{% endif %}

	<div class="t-dash"></div>
	{% if v.banner %}<div class="t-center t-bold t-banner">{{ v.banner }}</div>{% endif %}
