	<div class="t-dash"></div>

	{% if is_udhaar and current_balance > 0 %}
	<div class="t-duebox">
		<div class="t-center t-sm t-bold">BAAKI / BALANCE DUE</div>
		<div class="t-center t-bold t-due">Rs. {{ "%.2f"|format(current_balance) }}</div>
	</div>
