	<div class="t-dash"></div>
	<div class="t-row t-bold t-lg"><span>TOTAL</span><span>{{ doc.get_formatted("grand_total") }}</span></div>
	<div class="t-row t-sm"><span>PAID</span><span>{{ doc.get_formatted("paid_amount") }}</span></div>

