{# posting_time arrives as a timedelta through the PDF path but as a plain
   "HH:MM:SS" string through Desk's own print view — calling .total_seconds()
   blindly crashed the whole format there with "'str object' has no attribute
   'total_seconds'" (found 2026-08-23 opening this format from the Print
   button). Stringifying first works for both: str(timedelta) is also
   "H:MM:SS", so the same split parses either one. #}
{% set t_parts = (doc.posting_time | string).split(":") %}
{% set t_hh24 = (t_parts[0] | int) % 24 if t_parts | length > 1 else 0 %}
{% set t_mm = t_parts[1] | int if t_parts | length > 1 else 0 %}
{% set t_ampm = "AM" if t_hh24 < 12 else "PM" %}
{% set t_hh12 = t_hh24 % 12 %}
{% set t_hh12 = 12 if t_hh12 == 0 else t_hh12 %}
{% set posting_time_12h = "%02d:%02d %s" % (t_hh12, t_mm, t_ampm) %}

