	"Bill + Payment Receipt":   {"cls": "",          "cust": 1, "addr": 1, "price": 1, "qr": 1, "code": 0, "disc": 0, "acct": 1, "pay": 1, "sign": 0, "foot": 1, "banner": ""},
	"Delivery Slip (No Rates)": {"cls": "",          "cust": 1, "addr": 1, "price": 0, "qr": 0, "code": 1, "disc": 0, "acct": 0, "pay": 0, "sign": 1, "foot": 0, "banner": "DELIVERY SLIP - NOT A BILL"},
	"Large Print Bill":         {"cls": "v-large",   "cust": 1, "addr": 1, "price": 1, "qr": 1, "code": 0, "disc": 0, "acct": 1, "pay": 0, "sign": 0, "foot": 1, "banner": ""},
