	{% if customer_gstin %}<div class="santu-bill-customer-detail">GSTIN: {{ customer_gstin }}</div>{% endif %}
				{% if customer_place %}<div class="santu-bill-customer-detail">{{ customer_place }}</div>{% endif %}
			</td>
		</tr>
	</table>

	<table class="santu-bill-items">
		<thead>
			<tr>
				<th style="width: 6%">#</th>
				<th style="width: 40%">Item</th>
				<th class="num" style="width: 15%">Qty</th>
				<th class="num" style="width: 18%">Rate</th>
				<th class="num" style="width: 21%">Amount</th>
			</tr>
		</thead>
		<tbody>
			{% for item in doc.items %}
			<tr>
				<td>{{ loop.index }}</td>
				<td>{{ item.item_name or item.item_code }}</td>
				<td class="num">{{ item.qty | int if item.qty == item.qty | int else item.qty }} {{ frappe.call("santu_hardware.santu_hardware.api.uom_abbr", uom=item.uom) }}</td>
				<td class="num">{{ item.get_formatted("rate") }}</td>
				<td class="num">{{ item.get_formatted("amount") }}</td>
			</tr>
			{% endfor %}
		</tbody>
		<tfoot>
			<tr>
				<td colspan="2"></td>
				<td class="num">Total Qty</td>
				<td class="num" colspan="2">{{ total_qty | int if total_qty == total_qty | int else total_qty }}</td>
			</tr>
		</tfoot>
	</table>

	<table class="santu-bill-totals-table">
		{% if doc.discount_amount %}
		<tr><td>Discount</td><td class="value">- {{ doc.get_formatted("discount_amount") }}</td></tr>
		{% endif %}
		<tr class="grand"><td>Estimated Total</td><td class="value">{{ doc.get_formatted("grand_total") }}</td></tr>
	</table>
	<div class="santu-bill-words">{{ doc.in_words }}</div>

	<div class="santu-bill-signature-block">
		<div class="santu-bill-signature-line">For {{ doc.company }}</div>
		<div class="santu-bill-signature-sub">Authorised Signatory</div>
	</div>

	<div class="santu-bill-footer">
		<div class="thanks">Thank you for inquiring with {{ doc.company }}!</div>
		{% if company_website or company_email %}
		<div class="santu-bill-contact">
			{% if company_website %}<a href="{{ company_website if company_website.startswith('http') else 'https://' + company_website }}">{{ company_website | replace("https://", "") | replace("http://", "") }}</a>{% endif %}{% if company_website and company_email %} &nbsp;|&nbsp; {% endif %}{% if company_email %}<a href="mailto:{{ company_email }}">{{ company_email }}</a>{% endif %}
		</div>
		{% endif %}
	</div>
</div>

{% set pos_settings = frappe.get_doc("Santu POS Settings") %}
{% set company_addr_name = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, "parent") %}
{% set company_address = doc.company_address_display %}
{% set company_phone = None %}
{% set company_gstin = frappe.db.get_value("Company", doc.company, "gstin") %}
{% set company_website = frappe.db.get_value("Company", doc.company, "website") %}
{% set company_email = frappe.db.get_value("Company", doc.company, "email") %}
{% if company_addr_name %}
	{% set caddr2 = frappe.get_doc("Address", company_addr_name) %}
	{% set company_place = caddr2.county or caddr2.city %}
	{% set company_address = (caddr2.address_line1 + ", " if caddr2.address_line1 else "") + (caddr2.address_line2 + ", " if caddr2.address_line2 else "") + company_place + ", " + caddr2.state + " " + (caddr2.pincode or "") %}
	{% set company_phone = caddr2.phone %}
{% endif %}
{% set customer_name_val = doc.customer_name or doc.customer or "Valued Customer" %}
{% set customer_doc = frappe.get_doc("Customer", doc.customer) if (doc.customer and frappe.db.exists("Customer", doc.customer)) else None %}
{% set customer_mobile = (customer_doc.mobile_no if customer_doc else None) or doc.contact_mobile or doc.get("mobile_no") %}
{% set customer_village = customer_doc.santu_village if customer_doc else None %}
{% set customer_city = None %}
{% set customer_addr_line = None %}
{% set customer_state = None %}
{% if customer_doc and customer_doc.customer_primary_address %}
	{% set caddr = frappe.get_doc("Address", customer_doc.customer_primary_address) %}
	{% set customer_addr_line = caddr.address_line1 %}
	{% set customer_city = caddr.city %}
	{% set customer_state = caddr.state %}
{% endif %}
{% set customer_place = frappe.call("santu_hardware.santu_hardware.api.party_address_line", party_type="Customer", party=doc.customer) if doc.customer else None %}
{% set total_qty = doc.items | sum(attribute="qty") %}

<div class="santu-bill">
	<table class="santu-bill-header-table">
		<tr>
			<td style="width: 60%">
				{% set a4_logo = frappe.call("santu_hardware.santu_hardware.api.get_a4_logo_data_uri") if frappe.db.get_single_value("Santu POS Settings", "show_logo_on_a4_bill") else None %}
				{% if a4_logo %}
					<div style="margin-bottom: 8px;"><img src="{{ a4_logo }}" style="width: {{ pos_settings.a4_logo_width or 40 }}%; max-width: 100%; height: auto;"></div>
				{% else %}
					<div class="santu-bill-shop-name">{{ doc.company }}</div>
				{% endif %}
				<div class="santu-bill-shop-meta">
					{{ company_address or "" }}<br>
					{% if company_phone %}Phone: {{ company_phone }}<br>{% endif %}
					{% if company_gstin %}<b>GSTIN:</b> {{ company_gstin }}{% endif %}
				</div>
			</td>
			<td class="santu-bill-title-block" style="width: 40%">
				<div class="santu-bill-title">DELIVERY CHALLAN</div>
				<div class="santu-bill-meta-row"><b>Challan No:</b> {{ doc.name }}</div>
				<div class="santu-bill-meta-row"><b>Date:</b> {{ doc.get_formatted("posting_date") }}</div>
				{% if doc.lr_no %}<div class="santu-bill-meta-row"><b>LR/Transport No:</b> {{ doc.lr_no }}</div>{% endif %}
				{% if doc.vehicle_no %}<div class="santu-bill-meta-row"><b>Vehicle No:</b> {{ doc.vehicle_no }}</div>{% endif %}
				<span class="santu-bill-status-pill santu-bill-status-challan">
					{{ "Delivered" if doc.docstatus == 1 else "Dispatched" }}
				</span>
			</td>
		</tr>
	</table>

	<table class="santu-bill-customer-table">
		<tr>
			<td>
				<div class="santu-bill-customer-label">Delivered To / Party</div>
				<div class="santu-bill-customer-name">{{ customer_name_val }}</div>
				{% if customer_mobile %}<div class="santu-bill-customer-detail">Phone: {{ customer_mobile }}</div>{% endif %}
				{% if customer_place %}<div class="santu-bill-customer-detail">{{ customer_place }}</div>{% endif %}
			</td>
		</tr>
	</table>

	<table class="santu-bill-items">
		<thead>
			<tr>
				<th style="width: 8%">#</th>
				<th style="width: 62%">Item Description</th>
				<th class="num" style="width: 30%">Quantity Delivered</th>
			</tr>
		</thead>
		<tbody>
			{% for item in doc.items %}
			<tr>
				<td>{{ loop.index }}</td>
				<td><b>{{ item.item_name or item.item_code }}</b>{% if item.description and item.description != item.item_name %}<br><small style="color:#6b7280;">{{ item.description }}</small>{% endif %}</td>
				<td class="num"><b>{{ item.qty | int if item.qty == item.qty | int else item.qty }} {{ frappe.call("santu_hardware.santu_hardware.api.uom_abbr", uom=item.uom) }}</b></td>
			</tr>
			{% endfor %}
		</tbody>
		<tfoot>
			<tr>
				<td colspan="2"></td>
				<td class="num"><b>Total Quantity: {{ total_qty | int if total_qty == total_qty | int else total_qty }}</b></td>
			</tr>
		</tfoot>
	</table>

	<table class="santu-bill-signature-table" style="margin-top: 50px;">
		<tr>
			<td><div class="santu-bill-signature-line">Receiver's Signature / Stamp</div></td>
			<td><div class="santu-bill-signature-line">For {{ doc.company }}</div></td>
		</tr>
	</table>

	<div class="santu-bill-footer">
		<div class="thanks">Thank you for business with {{ doc.company }}!</div>
		{% if company_website or company_email %}
		<div class="santu-bill-contact">
			{% if company_website %}<a href="{{ company_website if company_website.startswith('http') else 'https://' + company_website }}">{{ company_website | replace("https://", "") | replace("http://", "") }}</a>{% endif %}{% if company_website and company_email %} &nbsp;|&nbsp; {% endif %}{% if company_email %}<a href="mailto:{{ company_email }}">{{ company_email }}</a>{% endif %}
		</div>
		{% endif %}
		<div class="legal">Goods delivered in good condition and order. E&amp;OE.</div>
	</div>
</div>

{% set pos_settings = frappe.get_doc("Santu POS Settings") %}
{% set company_addr_name = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, "parent") %}
{% set company_address = doc.company_address_display %}
{% set company_phone = None %}
{% set company_website = frappe.db.get_value("Company", doc.company, "website") %}
{% set company_email = frappe.db.get_value("Company", doc.company, "email") %}
{% if company_addr_name %}
	{% set caddr2 = frappe.get_doc("Address", company_addr_name) %}
	{% set company_place = caddr2.county or caddr2.city %}
	{% set company_address = (caddr2.address_line1 + ", " if caddr2.address_line1 else "") + (caddr2.address_line2 + ", " if caddr2.address_line2 else "") + company_place + ", " + caddr2.state + " " + (caddr2.pincode or "") %}
	{% set company_phone = caddr2.phone %}
{% endif %}
{% set customer_doc = frappe.get_doc("Customer", doc.customer) if doc.customer else None %}
{% set customer_mobile = (customer_doc.mobile_no if customer_doc else None) or doc.contact_mobile %}
{% set customer_gstin = customer_doc.gstin if customer_doc else None %}
{% set customer_village = customer_doc.santu_village if customer_doc else None %}
{% set customer_address = None %}
{% set customer_state = None %}
{% if customer_doc and customer_doc.customer_primary_address %}
	{% set caddr = frappe.get_doc("Address", customer_doc.customer_primary_address) %}
	{% set customer_address = caddr.address_line1 + ", " + caddr.city %}
	{% set customer_state = caddr.state %}
{% endif %}
{% set customer_place = frappe.call("santu_hardware.santu_hardware.api.party_address_line", party_type="Customer", party=doc.customer) if doc.customer else None %}
{% set due = doc.outstanding_amount | flt %}
{% set total_qty = doc.items | sum(attribute="qty") %}
{% set balances = frappe.call("santu_hardware.santu_hardware.api.get_customer_balance_summary", customer=doc.customer, exclude_doctype=doc.doctype, exclude_name=doc.name) %}
{% set previous_balance = balances.previous_balance | flt %}
{% set current_balance = previous_balance + due %}

<div class="santu-bill">
	<table class="santu-bill-header-table">
		<tr>
			<td style="width: 60%">
				{% set a4_logo = frappe.call("santu_hardware.santu_hardware.api.get_a4_logo_data_uri") if frappe.db.get_single_value("Santu POS Settings", "show_logo_on_a4_bill") else None %}
				{% if a4_logo %}
					<div style="margin-bottom: 8px;"><img src="{{ a4_logo }}" style="width: {{ pos_settings.a4_logo_width or 40 }}%; max-width: 100%; height: auto;"></div>
				{% else %}
					<div class="santu-bill-shop-name">{{ doc.company }}</div>
				{% endif %}

				<div class="santu-bill-shop-meta">
					{{ company_address or "" }}<br>
					{% if company_phone %}Phone: {{ company_phone }}<br>{% endif %}
				</div>
			</td>
			<td class="santu-bill-title-block" style="width: 40%">
				<div class="santu-bill-title">{% if doc.docstatus == 1 %}SALE BILL{% else %}ESTIMATE{% endif %}</div>
				<div class="santu-bill-meta-row"><b>Bill No:</b> {{ frappe.call("santu_hardware.santu_hardware.api.bill_label", bill_no=doc.santu_bill_no) }}</div>
				<div class="santu-bill-meta-row"><b>Date:</b> {{ doc.get_formatted("posting_date") }}</div>
				{% if due > 0 and doc.due_date %}<div class="santu-bill-meta-row"><b>Due Date:</b> {{ doc.get_formatted("due_date") }}</div>{% endif %}
				<span class="santu-bill-status-pill {{ 'santu-bill-status-due' if due > 0 else 'santu-bill-status-paid' }}">
					{{ "Payment Due" if due > 0 else "Paid" }}
				</span>
			</td>
		</tr>
	</table>

	<table class="santu-bill-customer-table">
		<tr>
			<td>
				<div class="santu-bill-customer-label">Billed To</div>
				<div class="santu-bill-customer-name">{{ doc.customer_name }}</div>
				{% if customer_mobile %}<div class="santu-bill-customer-detail">Phone: {{ customer_mobile }}</div>{% endif %}
	{% if customer_gstin %}<div class="santu-bill-customer-detail">GSTIN: {{ customer_gstin }}</div>{% endif %}
				{% if customer_place %}<div class="santu-bill-customer-detail">{{ customer_place }}</div>{% endif %}
			</td>
		</tr>
	</table>

	<table class="santu-bill-items">
		<thead>
			<tr>
				<th style="width: 6%">#</th>
				<th style="width: 40%">Item</th>
				<th class="num" style="width: 15%">Qty</th>
				<th class="num" style="width: 18%">Rate</th>
				<th class="num" style="width: 21%">Amount</th>
			</tr>
		</thead>
		<tbody>
			{% for item in doc.items %}
			<tr>
				<td>{{ loop.index }}</td>
				<td>{{ item.item_name }}</td>
				<td class="num">{{ item.qty | int if item.qty == item.qty | int else item.qty }} {{ frappe.call("santu_hardware.santu_hardware.api.uom_abbr", uom=item.uom) }}</td>
				<td class="num">{{ item.get_formatted("rate") }}</td>
				<td class="num">{{ item.get_formatted("amount") }}</td>
			</tr>
			{% endfor %}
		</tbody>
		<tfoot>
			<tr>
				<td colspan="2"></td>
				<td class="num">Total Qty</td>
				<td class="num" colspan="2">{{ total_qty | int if total_qty == total_qty | int else total_qty }}</td>
			</tr>
		</tfoot>
	</table>

	<table class="santu-bill-totals-table">
		{% if doc.discount_amount %}
		<tr><td>Discount</td><td class="value">- {{ doc.get_formatted("discount_amount") }}</td></tr>
		{% endif %}
		<tr class="grand"><td>Total</td><td class="value">{{ doc.get_formatted("grand_total") }}</td></tr>
		<tr><td>Paid</td><td class="value">{{ doc.get_formatted("paid_amount") }}</td></tr>
		{% if due > 0 %}
		<tr class="due"><td>Balance Due (This Bill)</td><td class="value">{{ doc.get_formatted("outstanding_amount") }}</td></tr>
		{% endif %}
	</table>
	<div class="santu-bill-words">{{ doc.in_words }}</div>

	<table class="santu-bill-panels">
		<tr>
			<td>
				<div class="santu-bill-panel">
					<div class="santu-bill-panel-title">Account Summary</div>
					<div class="santu-bill-panel-row"><span>Previous Balance</span><span>Rs. {{ "%.2f" | format(previous_balance) }}</span></div>
					<div class="santu-bill-panel-row"><span>Received Today</span><span>Rs. {{ "%.2f" | format(doc.paid_amount | flt) }}</span></div>
					<div class="santu-bill-panel-row emphasis {{ 'ok' if current_balance <= 0 else '' }}"><span>Current Balance</span><span>Rs. {{ "%.2f" | format(current_balance) }}</span></div>
				</div>
			</td>
		</tr>
	</table>

	<table class="santu-bill-signature-table">
		<tr>
			<td><div class="santu-bill-signature-line">Customer Signature</div></td>
			<td><div class="santu-bill-signature-line">For {{ doc.company }}</div></td>
		</tr>
	</table>

	<div class="santu-bill-footer">
		<div class="thanks">Thank you for shopping with {{ doc.company }}!</div>
		{% if company_website or company_email %}
		<div class="santu-bill-contact">
			{% if company_website %}<a href="{{ company_website if company_website.startswith('http') else 'https://' + company_website }}">{{ company_website | replace("https://", "") | replace("http://", "") }}</a>{% endif %}{% if company_website and company_email %} &nbsp;|&nbsp; {% endif %}{% if company_email %}<a href="mailto:{{ company_email }}">{{ company_email }}</a>{% endif %}
		</div>
		{% endif %}
		<div class="legal">Goods once sold can only be exchanged, not refunded. Bill is required for exchange. E&amp;OE.</div>
	</div>
</div>
